"""Generuje edytowalne źródła HTML raportu i slajdów na podstawie wyników testów."""
from pathlib import Path
import json
from html import escape

ROOT = Path(__file__).resolve().parents[1]
results = json.loads((ROOT / 'wyniki/testy.json').read_text())
ui = json.loads((ROOT / 'wyniki/interfejs.json').read_text())
comparison = json.loads((ROOT / 'wyniki/porownanie.json').read_text())


def table(headers, rows, cls=''):
    return '<table class="' + cls + '"><thead><tr>' + ''.join('<th>' + escape(str(h)) + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + escape(str(cell)) + '</td>' for cell in row) + '</tr>' for row in rows) + '</tbody></table>'


comparison_table = table(['n', '2ⁿ', 'Mnożenia zwykłe', 'Mnożenia szybkie', 'Stos zwykły', 'Stos szybki'], [[r['n'], r['result'], r['simpleMultiplications'], r['fastMultiplications'], r['simpleMaxStack'], r['fastMaxStack']] for r in comparison])
flow = '<div class="flow"><span>Wejście + walidacja</span><b>→</b><span>Algorytm + zdarzenia</span><b>→</b><span>Odtwarzacz stanu</span><b>→</b><span>Widok + pytanie</span></div>'
source_list = '''<ol class="sources"><li>[1] Karta zadania: ASD1-M1-14.html, „Rekurencja krok po kroku”, Dziennik UwB, rok 2026/2027. Wymagania i zakres liczb.</li><li>[2] R. Sedgewick, K. Wayne, Princeton, „2.3 Recursion”, <a href="https://introcs.cs.princeton.edu/java/23recursion/">introcs.cs.princeton.edu/java/23recursion/</a>, dostęp: 10.10.2026. Materiał pomocniczy dotyczący przypadków bazowych i Hanoi; nie wykorzystano gotowej wizualizacji.</li><li>[3] Własne artefakty projektu: app/algorithms.js, app/playback.js, tests/suite.js, tests/browser.cjs oraz wyniki/*.json. Źródło liczników, zrzutów i rzeczywistych wyników.</li></ol>'''
report_pages = [
('Rekurencja krok po kroku', '''<div class="cover"><p class="kicker">DZIENNIK UWB · MINI-PROJEKT M1</p><h1>Rekurencja<br>krok po kroku</h1><p class="subtitle">Interaktywne laboratorium wywołań,<br>przypadków bazowych i powrotów</p><div class="cover-rule"></div><dl><dt>Kod tematu</dt><dd>ASD1-M1-14</dd><dt>Autor / student</dt><dd>Edvin Zenevič</dd><dt>Numer indeksu</dt><dd>93783</dd><dt>Przedmiot</dt><dd>Algorytmy i struktury danych I</dd><dt>Rok akademicki</dt><dd>2026/2027 · semestr I</dd><dt>Data opracowania</dt><dd>10 października 2026</dd></dl><p>Dokumentacja techniczna i dydaktyczna · 10 stron</p><p class="muted">Aplikacja: index.html · Slajdy: prezentacja/prezentacja.html<br>Kolejność obrony: prezentacja → produkt → pytania</p></div>'''),
('Cel i zakres projektu', '''<h3>Problem dydaktyczny</h3><p>Rekurencja bywa błędnie rozumiana jako „funkcja powtarzająca samą siebie”. Kluczowe jest to, że każde wywołanie ma własne argumenty i czeka na wynik wywołania potomnego. Laboratorium pozwala obserwować oba kierunki pracy: zejście do przypadku bazowego oraz powroty, podczas których powstaje wynik. Odbiorcą jest student poznający rekurencję; celem jest samodzielne przewidywanie następnego kroku, a nie tylko oglądanie animacji.</p><h3>Zakres zgodny z kartą [1]</h3>''' + table(['Moduł', 'Dane', 'Przypadki bazowe'], [['Suma przez podział', '0–16 liczb całkowitych −20…20', 'Pusty fragment → 0; jeden element → jego wartość'], ['Potęgowanie zwykłe i szybkie', 'Podstawa −10…10; wykładnik 0…10', 'n = 0 → 1, także 0⁰; szybki także n = 1 → a'], ['Wieże Hanoi', '0–8 krążków, słupki A, B, C; cel A → C', 'n = 0 → zero ruchów']]) + '''<h3>Wykonane funkcje</h3><p>Jedna aplikacja zawiera wszystkie moduły. Użytkownik podaje własne dane i wybiera trzy scenariusze w każdym module. Sterowanie obejmuje Krok, Start/Pauza, Reset i tempo 100–2000 ms. Zmiana danych unieważnia poprzedni przebieg. Widoczne są: problem, aktywne ramki, argumenty, zmienne lokalne, drzewo z wynikami, bieżący wiersz pseudokodu i uzasadnienie zdarzenia.</p><p>Tryb przewidywania zatrzymuje pokaz przed wejściem lub powrotem. Pytanie zależy od rzeczywistego stosu. Dodatkowe trzy pytania mają odpowiedzi i wyjaśnienia. Tabela porównuje wyłącznie dwa warianty potęgowania na identycznych danych. Testy można uruchomić z aplikacji lub z Node.js.</p><h3>Warunki użycia i kryteria poprawności</h3><p>Program działa po otwarciu index.html w lokalnej przeglądarce, bez kont i płatnych usług. Nie wysyła danych do sieci. Wynik sumy i potęgi musi być zgodny z obliczeniami kontrolnymi; Hanoi kończy na C bez naruszenia kolejności krążków. Po ostatnim powrocie stos jest pusty, lecz drzewo zachowuje zakończone wywołania.</p><div class="note">Nie utożsamiamy stosu aktywnych wywołań z całym drzewem. Pierwszy opisuje „co jeszcze pracuje”, drugi „co zostało wywołane”.</div>'''),
('Algorytmy i mechanizmy', '''<h3>Suma przez podział</h3><p>Funkcja otrzymuje indeksy lo i hi opisujące półotwarty przedział [lo, hi). Dla lo = hi zwraca 0; dla hi − lo = 1 zwraca tablica[lo]. W pozostałych przypadkach mid = ⌊(lo + hi)/2⌋. Lewa i prawa połowa są obliczane kolejno, a dopiero po obu powrotach dodawane. Badany algorytm nie tworzy kopii połówek: kopia fragmentu występuje tylko w danych zdarzenia do wizualizacji.</p><p>Dla [2,4,1,3] liście zwracają 2, 4, 1 i 3. Połączenia dają 6 i 4, a korzeń 10. Poprawność wynika z rozłączności połówek i pokrycia całego przedziału. Każde wywołanie dla większego fragmentu zmniejsza jego długość.</p><h3>Dwa warianty potęgowania</h3><p>Wariant zwykły wykorzystuje aⁿ = a · aⁿ⁻¹. Jedyną bazą jest n = 0. Wariant szybki ma bazy n = 0 i n = 1, a dla większego n wywołuje funkcję raz dla ⌊n/2⌋ i zachowuje wynik half. Oblicza half · half; gdy n jest nieparzyste, dopisuje jeszcze czynnik a. Zwrócona wartość half jest użyta ponownie bez ponownego wywołania.</p><div class="note">Dla 2⁵: szybka ścieżka n = 5 → 2 → 1; powroty: 2 → 4 → 32. Są 3 mnożenia i maksymalnie 3 ramki. Zwykła ścieżka schodzi do 0: 5 mnożeń, 6 ramek.</div><p>Zmniejszenie wykładnika gwarantuje zakończenie. Tożsamości a²ᵏ = (aᵏ)² i a²ᵏ⁺¹ = (aᵏ)² · a uzasadniają poprawność również dla ujemnej podstawy. 0⁰ = 1 jest konwencją zadania, nie deklaracją uniwersalnej definicji matematycznej.</p><h3>Wieże Hanoi</h3><p>Dla n &gt; 0 funkcja przenosi n − 1 krążków z from na aux, następnie krążek n z from na to, a w końcu n − 1 z aux na to. Argumenty słupków zmieniają rolę w wywołaniach dzieci. Ruch ma identyfikator ramki, która go wykonała. Dla n = 0 emitowany jest przypadek bazowy i powrót z liczbą 0, ale nie ma ruchu.</p><p>Zakładając poprawne rozwiązanie dla n − 1, największy rozważany krążek jest odsłonięty, a cel legalny. Minimalna liczba ruchów spełnia M(n) = 2M(n − 1) + 1, M(0) = 0. Walidator sprawdza top źródła, top celu oraz cały stan po ruchu. Podejście odpowiada klasycznemu rozkładowi rekurencyjnemu [2], lecz kod i wizualizacja są realizacją projektu [3].</p>'''),
('Struktury danych i złożoność', '''<h3>Model zdarzenia i stan odtwarzania</h3><p>Każde zdarzenie zawiera type, id, parentId, depth, name, args, line i reason. Zależnie od typu dochodzą locals, value lub move = {disk, from, to}. Id jest unikatowe w obrębie przebiegu; parentId wiąże wywołanie z rodzicem. depth korzenia wynosi 0. Liczba aktywnych ramek wynosi depth + 1 przy wejściu do danego wywołania.</p><p>Stos to tablica: push przy wejściu, pop przy powrocie. Drzewo to Map indeksowana id z parentId i statusem active/finished; zakończony węzeł nie znika. Słupki Hanoi są trzema tablicami od dołu do góry: koniec tablicy oznacza górny krążek. Zmienna cursor wskazuje następne nieodtworzone zdarzenie. Zapisujemy jeden bieżący stan, nie kolekcję klatek.</p>''' + table(['Metoda', 'Czas obliczeń', 'Pamięć badanego algorytmu'], [['Suma, n ≥ 1', 'Θ(n), n − 1 dodawań', 'Stos Θ(log n); wejście Θ(n)'], ['Potęga zwykła', 'Θ(n + 1), n mnożeń', 'Stos Θ(n + 1)'], ['Potęga szybka, n ≥ 2', 'Θ(log n)', 'Stos Θ(log n)'], ['Hanoi', 'Θ(2ⁿ), 2ⁿ − 1 ruchów', 'Stos Θ(n + 1) i słupki Θ(n)']]) + '''<p class="caption">Tabela 1. Koszty bez instrumentacji; operacje na ograniczonych liczbach traktujemy jako O(1).</p><h3>Definicje liczników</h3><p>calls liczy każde wejście, również bazowe. maxDepth liczy największą liczbę aktywnych ramek, nie numer poziomu. multiplications liczy wyłącznie wykonane operacje * w potęgowaniu; additions — połączenia sum; moves — legalne przeniesienia Hanoi. W widoku pokazujemy liczniki odtworzonego prefiksu, w porównaniu — całego przebiegu. Dla pustych danych baza nadal wymaga jednej ramki.</p><h3>Narzut wizualizacji liczony oddzielnie</h3><p>Nie mierzymy czasu renderowania jako czasu algorytmu. Rejestr zdarzeń i węzły wymagają O(E) rekordów, gdzie E to liczba zdarzeń. Przy sumie zapis fragmentów daje łącznie O(n log n) skopiowanych liczb. Odtwarzanie przebudowuje do O(E) węzłów DOM na krok, więc cały pokaz może kosztować O(E²). Argumenty i nazwy w Hanoi mają stałą wielkość, ale walidacja pełnego układu ma O(n) na ruch i Set o O(n) pamięci.</p><p>Ograniczenia z karty utrzymują narzut na dydaktycznie użytecznym poziomie. To laboratorium śledzenia wykonania, nie biblioteka do obliczeń wysokowydajnych. Granice inputu są walidowane przed generowaniem śladu.</p>'''),
('Technologie i uruchomienie', '''<h3>Wybór technologii</h3><p>HTML definiuje semantyczne sekcje, formularze i tabele. CSS odpowiada za układ responsywny, kontrast i legendę. JavaScript zawiera badane algorytmy, odtwarzacz i obsługę interfejsu. Aplikacja nie używa bibliotek interfejsu, bundlera, CDN ani API. Dzięki klasycznym skryptom zamiast importów modułów można otworzyć index.html z file:// bez serwera.</p><p>Algorytmy oraz testy udostępniają te same funkcje przeglądarce i Node.js. Ograniczenie |a| ≤ 10, n ≤ 10 daje najwyżej 10¹⁰, czyli wartość poniżej Number.MAX_SAFE_INTEGER. Nie potrzebujemy BigInt. Dla większych zakresów należałoby ponownie sprawdzić precyzję i model kosztu arytmetyki.</p><h3>Uruchomienie aplikacji i testów</h3><ol><li>Rozpakuj archiwum, zachowując strukturę folderów.</li><li>Otwórz index.html w aktualnej przeglądarce, np. Firefox, Chrome lub Edge.</li><li>Wybierz moduł, dane i przycisk Krok albo Start.</li><li>Przycisk „Uruchom testy lokalnie” uruchamia tę samą podstawową serię 44 testów bez instalacji.</li><li>W terminalu, mając Node.js, wykonaj <code>node tests/run.cjs</code>. Opcja <code>--save</code> odświeża pliki wyniki/testy.json, testy.txt (po przekierowaniu wyjścia) i porownanie.json.</li></ol><h3>Narzędzia weryfikacji i dokumentacji</h3><p>Node.js uruchamia testy. Playwright steruje Chromium w dodatkowej serii testów interfejsu: kliknięcia, zmiana pól, pytania, tryb bez sieci, ekran mobilny. Ten zestaw wymaga pomocniczej instalacji Playwright; nie jest wymagany dla odbiorcy aplikacji. Skrypt tests/browser.cjs odtwarza weryfikację i zapisuje zrzuty z rzeczywistego widoku.</p><p>Python 3 przygotowuje źródła dokumentów HTML. Chromium eksportuje dokumentację i slajdy do PDF. pdf-lib sprawdza liczbę stron. To wyłącznie narzędzia wytwarzania, nie zależności produktu. Sposób odtworzenia podaje README.</p><h3>Pliki do obrony</h3><p><strong>prezentacja/prezentacja.html</strong> i <strong>prezentacja/prezentacja.pdf</strong> zawierają dokładnie 10 slajdów. <strong>dokumentacja/dokumentacja.pdf</strong> zawiera 10 stron. HTML raportu jest źródłem edytowalnym, nie zamiennikiem wymaganego PDF. Do demonstracji służy index.html; wyniki testów dostępne są w aplikacji i folderze wyniki.</p><div class="note">Brak internetu nie blokuje aplikacji, testów w przeglądarce ani slajdów. Link do materiału Princeton jest źródłem do nauki, nie zasobem ładowanym przez produkt.</div>'''),
('Architektura i realizacja', flow + '''<p class="caption">Rysunek 1. Przepływ danych: obliczenia są oddzielone od odtwarzania i DOM.</p>''' + table(['Plik', 'Odpowiedzialność'], [['app/algorithms.js', 'Walidacja, rekurencja, zdarzenia, metryki, legalność Hanoi, porównanie'], ['app/playback.js', 'Stan, stos, drzewo, odtwarzanie jednego zdarzenia, pytanie zależne od stanu'], ['app/content.js', 'Polskie opisy, zastosowania, ograniczenia i pseudokod'], ['app/ui.js + app/styles.css', 'Formularze, scenariusze, zegar, renderowanie, odpowiedzi i testy'], ['tests/suite.js + tests/run.cjs', 'Wspólne testy domenowe oraz zapis wyników w Node.js'], ['tests/browser.cjs', 'Weryfikacja prawdziwego interfejsu i zrzuty'], ['narzedzia/', 'Generacja źródeł i eksport dokumentów']]) + '''<h3>Rzeczywisty ślad zamiast ręcznej animacji</h3><p>createTrace wykonuje funkcje rekurencyjne synchronicznie i zapisuje zdarzenia w miejscu faktycznych operacji. Później advance odtwarza pojedynczy prefiks śladu. Animacja nie wykonuje ponownie rekurencji ani nie korzysta z nagrania. Odtwarzacz kontroluje, czy zdarzenie dotyczy szczytu stosu i czy rodzic nowej ramki jest aktualnym wywołaniem. Takie rozdzielenie umożliwia niezależny test obliczeń oraz stanu po dowolnym zdarzeniu.</p><h3>Etapy wykonania</h3><p>Najpierw ustalono zakres i model zdarzenia. Potem zaimplementowano wszystkie metody i walidator Hanoi. Następnie powstał odtwarzacz, polskie opisy i interfejs. Testy bazowe, końcowe i pośrednie uruchomiono przed stworzeniem dokumentów. Kolejny etap obejmował automatyczne testy przeglądarki oraz zrzuty. Na końcu opracowano porównanie, slajdy i raport na podstawie rzeczywistych danych.</p><h3>Obsługa nowego przebiegu i błędów</h3><p>Zmiana wejścia zatrzymuje timer i czyści pytanie. Poprawne dane tworzą nowy ślad i pusty stan. Niepoprawne dane unieważniają stary ślad, blokują Krok/Start i wyświetlają przyczynę; nie pokazujemy starego wyniku jako aktualnego. Reset zachowuje wejście, lecz czyści odtworzenie. Tempo zmienia tylko harmonogram odtwarzania, nie wynik czy liczniki algorytmu.</p><p>Interfejs nie zna reguł rekurencji: pobiera stan i treść z osobnych modułów. Dzięki temu poprawność nie zależy od szybkości animacji ani rozmiaru ekranu.</p>'''),
('Interfejs i obsługa', '''<img class="screenshot" src="suma-stan.png" alt="Stan sumowania po powrocie pierwszego liścia"><p class="caption">Rysunek 2. Rzeczywisty widok po powrocie #3 dla [2,4,1,3]. Ramka #3 zwróciła 2 i znikła ze stosu; pozostały #2 oraz #1. W drzewie wynik #3 jest zachowany.</p><img class="screenshot" src="hanoi-stan.png" alt="Stan Hanoi po pierwszym ruchu"><p class="caption">Rysunek 3. Pierwszy ruch Hanoi dla n = 3: krążek 1 trafia z A na C. Węzeł #3 wiąże ruch z odpowiednim wywołaniem; aktywny stos ma trzy ramki.</p><h3>Przebieg demonstracji</h3><p>Przyciski modułów przełączają problem. W scenariuszu kontrolnym Krok pokazuje jedno zdarzenie, a Start kontynuuje według wybranego tempa. Pauza przerywa zegar bez zmiany stanu. Reset wraca przed pierwsze wejście. Gdy pokaz jest zakończony, Krok i Start są nieaktywne; można zresetować albo zmienić dane.</p><h3>Legenda i dostępność</h3><p>▲ oznacza szczyt stosu, ● aktywne wywołanie, ✓ zakończone, ↳ dziecko, ▶ aktualny wiersz pseudokodu. Zakończenie, ruch i wynik mają opis tekstowy. Różnice nie są kodowane wyłącznie kolorem. Formularze mają etykiety, przyciski są dostępne z klawiatury, a błędy wejścia są ogłaszane przez role=alert. Na wąskim ekranie kolumny przechodzą do układu pionowego, a duże tabele mają własne przewijanie.</p><h3>Pytanie o aktualny stan</h3><p>Włączenie „Zatrzymuj przed wejściem / powrotem” powoduje pytanie przed wykonaniem zdarzenia. Dla wejścia trzeba przewidzieć liczbę ramek; dla powrotu — przyszły szczyt stosu. Błędna odpowiedź nie odblokowuje kroku. Poprawna ujawnia wyjaśnienie i pozwala wykonać dokładnie przewidziane zdarzenie. Nie przeskakujemy automatycznie przez pytanie.</p>'''),
('Porównanie potęgowania', '''<h3>Metoda pomiaru</h3><p>Porównanie wykonano dla podstawy 2 i wykładników 1, 4, 8, 10. Każda komórka pochodzi z pełnego wykonania createTrace, a nie z pomiaru czasu animacji. Rozmiar wejścia oznacza wartość wykładnika n. Przy nieograniczonych liczbach należałoby odróżnić tę miarę od długości bitowej oraz uwzględnić koszt mnożenia wielkich liczb.</p>''' + comparison_table + '''<p class="caption">Tabela 2. Rzeczywiste wyniki zapisane w wyniki/porownanie.json [3]. Stos oznacza liczbę ramek, korzeń = 1.</p><h3>Interpretacja</h3><p>Oba warianty dają identyczny wynik. Zwykły wykonuje dokładnie n mnożeń i przechowuje n + 1 ramek, gdyż schodzi do wykładnika 0. Szybki wykorzystuje dodatkową bazę n = 1. Dla potęg dwójki (4 i 8) każdy poziom nad bazą potrzebuje tylko kwadratu. Dla n = 10 ścieżka wykładników to 10 → 5 → 2 → 1: występują trzy kwadraty oraz jedno dodatkowe mnożenie dla wykładnika 5.</p><p>Nieparzyste wykładniki wpływają na liczbę mnożeń, ale nie wydłużają ścieżki względem połowienia. Ogólnie dla n ≥ 1 liczba mnożeń szybkiego wariantu wynosi ⌊log₂ n⌋ + popcount(n) − 1. popcount to liczba jedynek w zapisie binarnym. Dla n = 10 (1010₂) mamy 3 + 2 − 1 = 4.</p><div class="note">Dla 2¹ wynik obu metod to 2. Zwykła mnoży 2 · 1, szybka od razu zwraca 2. Dlatego w pierwszym wierszu występuje 1 wobec 0, a nie 1 wobec 2.</div><h3>Czego nie wynika z tabeli</h3><p>Nie jest to benchmark czasu ściennego. W małym zakresie narzut zapisu zdarzeń i renderowania może dominować, a różnica kilku mnożeń nie musi być widoczna w czasie zegarowym. Liczniki pokazują pracę algorytmiczną. Nie sumujemy mnożeń, dodawań i ruchów w jeden ranking: odnoszą się do różnych problemów i innych jednostek pracy.</p><h3>Porównanie z przykładem kontrolnym</h3><p>Dla 2⁵, użytego w aplikacji, wyniki wynoszą 32. Zwykły wariant ma 5 mnożeń i 6 ramek, szybki 3 mnożenia i 3 ramki. Dla sumy [2,4,1,3] wynik to 10 i 3 dodawania; Hanoi dla 3 krążków kończy po 7 ruchach. Te wartości potwierdzają osobne testy, lecz nie dodajemy ich do porównania potęgowania.</p>'''),
('Testowanie i wyniki', f'''<p>Podstawowa seria: <strong>{results['passed']}/{results['total']} PASS</strong>. Uruchomiono: {escape(results['executedAt'])}. Ta sama seria przeszła w przeglądarce. Testy interfejsu: <strong>{ui['passed']}/{ui['total']} PASS</strong>, Chromium {escape(ui['browser'])}, {escape(ui['executedAt'])}. Wykonano je z zablokowanymi żądaniami HTTP/HTTPS.</p>''' + table(['Wejście / sprawdzenie', 'Oczekiwane i uzyskane', 'Status'], [['Suma []', '0', 'PASS'], ['Suma [-7]', '−7', 'PASS'], ['Suma [2,4,1,3]', '10', 'PASS'], ['Obie potęgi: 0⁰ i 5⁰', '1', 'PASS'], ['Obie potęgi: (−7)¹', '−7', 'PASS'], ['Obie potęgi: 2⁵ i (−2)⁵', '32 i −32', 'PASS'], ['Hanoi n = 0, 1, 3, 8', '0, 1, 7, 255 ruchów; całość na C', 'PASS'], ['Suma po pierwszym powrocie', 'Stos [#1,#2]; #3 = 2, finished', 'PASS'], ['Hanoi po pierwszym ruchu', 'A=[3,2], B=[], C=[1]; stos [1,2,3]', 'PASS'], ['Niepoprawny zakres i ułamki', 'Wejście odrzucone', 'PASS'], ['Większy na mniejszym / duplikat / brak', 'Stan odrzucony', 'PASS'], ['Wszystkie metody po zakończeniu', 'Pusty stos, finished, metryki zgodne', 'PASS'], ['Cała dziedzina potęgowania', '462 zgodne przebiegi, ** jako oracle', 'PASS']], 'compact') + '''<p class="caption">Tabela 3. Skrót pokrycia. Każdy z 44 testów ma osobno nazwę, wejście, oczekiwane, uzyskane i status w wyniki/testy.json oraz testy.txt. Taką tabelę wyświetla też aplikacja.</p><h3>Dwa stany pośrednie i niezależna kontrola</h3><p>Nie wystarcza sam wynik końcowy. Pierwszy test pośredni potwierdza usunięcie zakończonej ramki sumy i zachowanie wyniku w drzewie. Drugi sprawdza pierwszy ruch Hanoi, układ słupków oraz id aktywnego wywołania. Oczekiwania są zapisane jawnie, niezależnie od rendererów. Dla potęg oracle jest operator **; dla Hanoi sprawdzane są 2ⁿ − 1 ruchów, docelowa wieża i legalność po każdym ruchu.</p><h3>Kontrole interfejsu i naprawione problemy środowiska</h3><p>17 kontroli obejmuje otwarcie file://, Krok, wyróżnienie kodu, Reset, własne i błędne dane, scenariusze, Start/Pauza/tempo, dobre i złe odpowiedzi, oba warianty potęgi, Hanoi, tabelę, testy przeglądarkowe, widok mobilny i brak błędów JavaScript. Pierwsze uruchomienie narzędzia Chromium ujawniło brak bibliotek systemowych; rozpakowano wymagane biblioteki w tymczasowym katalogu bez zmiany konfiguracji serwera. Nie był to błąd algorytmu. W wykonanych seriach nie wykryto niezgodnych wyników domenowych.</p>'''),
('Podsumowanie, źródła i AI', '''<h3>Wnioski</h3><p>Przypadek bazowy zatrzymuje zejście, ale nie kończy całej pracy: wyniki są składane podczas powrotów. Stos pokazuje aktywną ścieżkę, a drzewo pełną historię wywołań. Szybkie potęgowanie redukuje wzrost czasu i stosu z liniowego do logarytmicznego. Hanoi pokazuje, że niewielki stos nie oznacza małej liczby operacji: głębokość jest liniowa, lecz liczba ruchów wykładnicza.</p><h3>Ograniczenia i rozwój</h3><p>Zakresy wejścia są celowo ograniczone kartą. Rejestr zdarzeń powstaje przed odtwarzaniem, więc aplikacja nie jest debuggerem wstrzymującym rzeczywisty stos silnika JavaScript. Rekonstrukcja stanu jest jednak zgodna z prawdziwymi zdarzeniami wykonania i sprawdzana testami. Przebudowa drzewa DOM jest czytelna i prosta, lecz dla dużych śladów wymagałaby aktualizacji przyrostowej lub wirtualizacji. Możliwy rozwój to generatory zdarzeń na żądanie i potęgowanie modularne z BigInt; nie są one częścią tej pracy.</p><h3>Wykorzystanie narzędzi AI i wkład</h3><p>Użyto OpenAI Codex przez OpenClaw do analizy karty, przygotowania kodu, testów, źródeł dokumentów, scenariusza obrony i weryfikacji. Kod oraz materiały tego pakietu powstały przy istotnym udziale AI. Nie deklarujemy, że student samodzielnie napisał każdy plik lub przeprowadził opisane testy ręcznie. Rzeczywiste uruchomienia wykonał agent; ich wyniki zapisano w pakiecie.</p><p>Potwierdzony wkład Edvina: wybór i przekazanie zadania, miejsca zapisu i danych autora. Przed oddaniem należy przejrzeć kod, przećwiczyć obronę i dopisać tylko faktycznie wykonane własne zmiany. Gotowy produkt nie zastępuje samodzielnego wyjaśnienia implementacji.</p><h3>Jak kontrolowano wynik AI</h3><p>Sprawdzono kontrakty wejścia, jawne oczekiwania testów, wyczerpującą dziedzinę potęgowania, legalność Hanoi, dwa stany pośrednie i zgodność liczników. Interfejs uruchomiono bez sieci; z niego pochodzą podpisane zrzuty. Nie użyto filmu ani skopiowanej wizualizacji. Wyników nie zadeklarowano przed wykonaniem testów.</p><h3>Materiały i odwołania</h3>''' + source_list + '''<div class="note">Przy oddawaniu: aplikacja i kod + prezentacja + raport PDF. Osobno dodaj link repozytorium GitHub do pola „Linki” w Dzienniku. Repozytorium nie zastępuje plików. Termin: 26.10.2026, 23:59; obrona: 28.10.2026, 08:30–11:40 [1].</div>''')]
